#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    vector<long long> a(n);
    for (auto &x : a) scanf("%lld", &x);
    vector<int> s(q), t(q);
    for (auto &x : s) scanf("%d", &x);
    for (auto &x : t) scanf("%d", &x);
    // R[i]: cost of stepping i -> i+1; L[i]: cost of stepping i -> i-1 (1 if that neighbour is nearest).
    vector<long long> R(n, 0), L(n, 0);
    for (int i = 0; i < n; i++) {
        if (i + 1 < n) R[i] = (i == 0 || a[i + 1] - a[i] < a[i] - a[i - 1]) ? 1 : a[i + 1] - a[i];
        if (i) L[i] = (i == n - 1 || a[i] - a[i - 1] < a[i + 1] - a[i]) ? 1 : a[i] - a[i - 1];
    }
    vector<long long> pr(n + 1, 0), pl(n + 1, 0);
    for (int i = 0; i < n; i++) { pr[i + 1] = pr[i] + R[i]; pl[i + 1] = pl[i] + L[i]; }
    string out;
    for (int i = 0; i < q; i++) {
        int x = s[i], y = t[i];
        long long v = x < y ? pr[y] - pr[x] : x > y ? pl[x + 1] - pl[y + 1] : 0;
        if (i) out += ' ';
        out += to_string(v);
    }
    puts(out.c_str());
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int[] s = new int[q], t = new int[q];
        for (int i = 0; i < q; i++) s[i] = nextInt();
        for (int i = 0; i < q; i++) t[i] = nextInt();
        // R[i]: cost of stepping i -> i+1; L[i]: cost of stepping i -> i-1 (1 if that neighbour is nearest).
        long[] R = new long[n], L = new long[n];
        for (int i = 0; i < n; i++) {
            if (i + 1 < n) R[i] = (i == 0 || a[i + 1] - a[i] < a[i] - a[i - 1]) ? 1 : a[i + 1] - a[i];
            if (i > 0) L[i] = (i == n - 1 || a[i] - a[i - 1] < a[i + 1] - a[i]) ? 1 : a[i] - a[i - 1];
        }
        long[] pr = new long[n + 1], pl = new long[n + 1];
        for (int i = 0; i < n; i++) { pr[i + 1] = pr[i] + R[i]; pl[i + 1] = pl[i] + L[i]; }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int x = s[i], y = t[i];
            long v = x < y ? pr[y] - pr[x] : x > y ? pl[x + 1] - pl[y + 1] : 0;
            if (i > 0) sb.append(' ');
            sb.append(v);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, q := readInt(), readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	s, t := make([]int, q), make([]int, q)
	for i := range s {
		s[i] = readInt()
	}
	for i := range t {
		t[i] = readInt()
	}
	// R[i]: cost of stepping i -> i+1; L[i]: cost of stepping i -> i-1 (1 if that neighbour is nearest).
	R, L := make([]int, n), make([]int, n)
	for i := 0; i < n; i++ {
		if i+1 < n {
			if i == 0 || a[i+1]-a[i] < a[i]-a[i-1] {
				R[i] = 1
			} else {
				R[i] = a[i+1] - a[i]
			}
		}
		if i > 0 {
			if i == n-1 || a[i]-a[i-1] < a[i+1]-a[i] {
				L[i] = 1
			} else {
				L[i] = a[i] - a[i-1]
			}
		}
	}
	pr, pl := make([]int, n+1), make([]int, n+1)
	for i := 0; i < n; i++ {
		pr[i+1] = pr[i] + R[i]
		pl[i+1] = pl[i] + L[i]
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for i := 0; i < q; i++ {
		x, y := s[i], t[i]
		v := 0
		if x < y {
			v = pr[y] - pr[x]
		} else if x > y {
			v = pl[x+1] - pl[y+1]
		}
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(v))
	}
	w.WriteByte('\n')
}
